package com.creativeblisslabs.peqlearn.app.util

data class PianoChordData(
    val key: String,
    val suffix: String,
    val notes: List<String>,
    val intervals: List<String>,
    val midi: List<Int>
)

object RealPianoChordsDb {
    val keys = listOf("C", "C#", "D", "Eb", "E", "F", "F#", "G", "Ab", "A", "Bb", "B")
    
    val suffixes = listOf(
        "major", "m", "dim", "dim7", "sus2", "sus4", "7sus4", "aug", "aug7", "aug9",
        "5", "6", "69", "7", "7b5", "7b9", "7sharp9", "9", "9b5", "11", "13",
        "add9", "maj7", "maj7b5", "maj7sharp5", "maj9", "maj11", "maj13",
        "m6", "m69", "m7", "m7b5", "m9", "m11", "mmaj7", "mmaj7b5", "madd9"
    )

    fun getChord(key: String, suffix: String): PianoChordData? {
        val normKey = when (key.uppercase()) {
            "DB" -> "C#"
            "D#" -> "Eb"
            "GB" -> "F#"
            "G#" -> "Ab"
            "A#" -> "Bb"
            else -> key
        }
        val normSuffix = when (suffix.lowercase()) {
            "minor" -> "m"
            "min" -> "m"
            "maj" -> "major"
            "dom7" -> "7"
            else -> suffix
        }
        return getByRoot(normKey).find { it.suffix.equals(normSuffix, ignoreCase = true) }
    }

    fun getByRoot(key: String): List<PianoChordData> {
        return when (key) {
            "C" -> chordsC
            "C#" -> chordsCsharp
            "D" -> chordsD
            "Eb" -> chordsEb
            "E" -> chordsE
            "F" -> chordsF
            "F#" -> chordsFsharp
            "G" -> chordsG
            "Ab" -> chordsAb
            "A" -> chordsA
            "Bb" -> chordsBb
            "B" -> chordsB
            else -> emptyList()
        }
    }

